 'C1010026','C2010029','06050388','C1010027','C3010059','C3020095','C4010048',
 'C1010023','C2010036','C4010037','45460510','C4010028','C1010028','C2010028',
 'C2010038','C4010030','C4010040','C2010031','C2010032','C2010039','C2010041',
 'C3020100','C4010029','C2010025','C4010033','45030765','C1010022','C4010036',
 'C4010039','C1010025','C2010040','45072000','C2010026')
group by distribuicao, produto, data

